ntType":"application/json","integrity":"sha384-n5IgkYTjTfp9jox3SIyKvOGe4p9uieX/71l5ZmDP83cNO6zSIcCZe3lGx4JHfGwg","language":"Source Map (JSON)","size":127580,"uri":null,"highlights":["{<span class=\"code-attr\">\"version\"</span>:<span class=\"code-number\">3</span>,<span class=\"code-attr\">\"file\"</span>:<span class=\"code-string\">\"popper.js\"</span>,<span class=\"code-attr\">\"sources\"</span>:[<span class=\"code-string\">\"../src/utils/debounce.js\"</span>,<span class=\"code-string\">\"../src/utils/isFunction.js\"</span>,<span class=\"code-string\">\"../src/utils/getStyleComputedProperty.js\"</span>,<span class=\"code-string\">\"../src/utils/getParentNode.js\"</span>,<span class=\"code-string\">\"../src/utils/getScrollParent.js\"</span>,<span class=\"code-string\">\"../src/utils/getOffsetParent.js\"</span>,<span class=\"code-string\">\"../src/utils/isOffsetContainer.js\"</span>,<span class=\"code-string\">\"../src/utils/getRoot.js\"</span>,<span class=\"code-string\">\"../src/utils/findCommonOffsetParent.js\"</span>,<span class=\"code-string\">\"../src/utils/getScroll.js\"</span>,<span class=\"code-string\">\"../src/utils/includeScroll.js\"</span>,<span class=\"code-string\">\"../src/utils/getBordersSize.js\"</span>,<span class=\"code-string\">\"../src/utils/isIE10.js\"</span>,<span class=\"code-string\">\"../src/utils/getWindowSizes.js\"</span>,<span class=\"code-string\">\"../src/utils/getClientRect.js\"</span>,<span class=\"code-string\">\"../src/utils/getBoundingClientRect.js\"</span>,<span class=\"code-string\">\"../src/utils/getOffsetRectRelativeToArbitraryNode.js\"</span>,<span class=\"code-string\">\"../src/utils/getViewportOffsetRectRelativeToArtbitraryNode.js\"</span>,<span class=\"code-string\">\"../src/utils/isFixed.js\"</span>,<span class=\"code-string\">\"../src/utils/getBoundaries.js\"</span>,<span class=\"code-string\">\"../src/utils/computeAutoPlacement.js\"</span>,<span class=\"code-string\">\"../src/utils/getReferenceOffsets.js\"</span>,<span class=\"code-string\">\"../src/utils/getOuterSizes.js\"</span>,<span class=\"code-string\">\"../src/utils/getOppositePlacement.js\"</span>,<span class=\"code-string\">\"../src/utils/getPopperOffsets.js\"</span>,<span class=\"code-string\">\"../src/utils/find.js\"</span>,<span class=\"code-string\">\"../src/utils/findIndex.js\"</span>,<span class=\"code-string\">\"../src/utils/runModifiers.js\"</span>,<span class=\"code-string\">\"../src/methods/update.js\"</span>,<span class=\"code-string\">\"../src/utils/isModifierEnabled.js\"</span>,<span class=\"code-string\">\"../src/utils/getSupportedPropertyName.js\"</span>,<span class=\"code-string\">\"../src/methods/destroy.js\"</span>,<span class=\"code-string\">\"../src/utils/getWindow.js\"</span>,<span class=\"code-string\">\"../src/utils/setupEventListeners.js\"</span>,<span class=\"code-string\">\"../src/methods/enableEventListeners.js\"</span>,<span class=\"code-string\">\"../src/utils/removeEventListeners.js\"</span>,<span class=\"code-string\">\"../src/methods/disableEventListeners.js\"</span>,<span class=\"code-string\">\"../src/utils/isNumeric.js\"</span>,<span class=\"code-string\">\"../src/utils/setStyles.js\"</span>,<span class=\"code-string\">\"../src/utils/setAttributes.js\"</span>,<span class=\"code-string\">\"../src/modifiers/applyStyle.js\"</span>,<span class=\"code-string\">\"../src/modifiers/computeStyle.js\"</span>,<span class=\"code-string\">\"../src/utils/isModifierRequired.js\"</span>,<span class=\"code-string\">\"../src/modifiers/arrow.js\"</span>,<span class=\"code-string\">\"../src/utils/getOppositeVariation.js\"</span>,<span class=\"code-string\">\"../src/methods/placements.js\"</span>,<span class=\"code-string\">\"../src/utils/clockwise.js\"</span>,<span class=\"code-string\">\"../src/modifiers/flip.js\"</span>,<span class=\"code-string\">\"../src/modifiers/keepTogether.js\"</span>,<span class=\"code-string\">\"../src/modifiers/offset.js\"</span>,<span class=\"code-string\">\"../src/modifiers/preventOverflow.js\"</span>,<span class=\"code-string\">\"../src/modifiers/shift.js\"</span>,<span class=\"code-string\">\"../src/modifiers/hide.js\"</span>,<span class=\"code-string\">\"../src/modifiers/inner.js\"</span>,<span class=\"code-string\">\"../src/modifiers/index.js\"</span>,<span class=\"code-string\">\"../src/methods/defaults.js\"</span>,<span class=\"code-string\">\"../src/index.js\"</span>],<span class=\"code-attr\">\"sourcesContent\"</span>:[<span class=\"code-string\">\"const isBrowser = typeof window !== 'undefined' &amp;&amp; typeof document !== 'undefined';\\nconst longerTimeoutBrowsers = ['Edge', 'Trident', 'Firefox'];\\nlet timeoutDuration = 0;\\nfor (let i = 0; i &lt; longerTimeoutBrowsers.length; i += 1) {\\n  if (isBrowser &amp;&amp; navigator.userAgent.indexOf(longerTimeoutBrowsers[i]) &gt;= 0) {\\n    timeoutDuration = 1;\\n    break;\\n  }\\n}\\n\\nexport function microtaskDebounce(fn) {\\n  let called = false\\n  return () =&gt; {\\n    if (called) {\\n      return\\n    }\\n    called = true\\n    window.Promise.resolve().then(() =&gt; {\\n      called = false\\n      fn()\\n    })\\n  }\\n}\\n\\nexport function taskDebounce(fn) {\\n  let scheduled = false;\\n  return () =&gt; {\\n    if (!scheduled) {\\n      scheduled = true;\\n      setTimeout(() =&gt; {\\n        scheduled = false;\\n        fn();\\n      }, timeoutDuration);\\n    }\\n  };\\n}\\n\\nconst supportsMicroTasks = isBrowser &amp;&amp; window.Promise\\n\\n\\n/**\\n* Create a debounced version of a method, that's asynchronously deferred\\n* but called in the minimum time possible.\\n*\\n* @method\\n* @memberof Popper.Utils\\n* @argument {Function} fn\\n* @returns {Function}\\n*/\\nexport default (supportsMicroTasks\\n  ? microtaskDebounce\\n  : taskDebounce);\\n\"</span>,<span class=\"code-string\">\"/**\\n * Check if the given variable is a function\\n * @method\\n * @memberof Popper.Utils\\n * @argument {Any} functionToCheck - variable to check\\n * @returns {Boolean} answer to: is a function?\\n */\\nexport default function isFunction(functionToCheck) {\\n  const getType = {};\\n  return (\\n    functionToCheck &amp;&amp;\\n    getType.toString.call(functionToCheck) === '[object Function]'\\n  );\\n}\\n\"</span>,<span class=\"code-string\">\"/**\\n * Get CSS computed property of the given element\\n * @method\\n * @memberof Popper.Utils\\n * @argument {Eement} element\\n * @argument {String} property\\n */\\nexport default function getStyleComputedProperty(element, property) {\\n  if (element.nodeType !== 1) {\\n    return [];\\n  }\\n  // NOTE: 1 DOM access here\\n  const css = getComputedStyle(element, null);\\n  return property ? css[property] : css;\\n}\\n\"</span>,<span class=\"code-string\">\"/**\\n * Returns the parentNode or the host of the element\\n * @method\\n * @memberof Popper.Utils\\n * @argument {Element} element\\n * @returns {Element} parent\\n */\\nexport default function getParentNode(element) {\\n  if (element.nodeName === 'HTML') {\\n    return element;\\n  }\\n  return element.parentNode || element.host;\\n}\\n\"</span>,<span class=\"code-string\">\"import getStyleComputedProperty from './getStyleComputedProperty';\\nimport getParentNode from './getParentNode';\\n\\n/**\\n * Returns the scrolling parent of the given element\\n * @method\\n * @memberof Popper.Utils\\n * @argument {Element} element\\n * @returns {Element} scroll parent\\n */\\nexport default function getScrollParent(element) {\\n  // Return body, `getScroll` will take care to get the correct `scrollTop` from it\\n  if (!element) {\\n    return document.body\\n  }\\n\\n  switch (element.nodeName) {\\n    case 'HTML':\\n    case 'BODY':\\n      return element.ownerDocument.body\\n    case '#document':\\n      return element.body\\n  }\\n\\n  // Firefox want us to check `-x` and `-y` variations as well\\n  const { overflow, overflowX, overflowY } = getStyleComputedProperty(element);\\n  if (/(auto|scroll)/.test(overflow + overflowY + overflowX)) {\\n    return element;\\n  }\\n\\n  return getScrollParent(getParentNode(element));\\n}\\n\"</span>,<span class=\"code-string\">\"import getStyleComputedProperty from './getStyleComputedProperty';\\n/**\\n * Returns the offset parent of the given element\\n * @method\\n * @memberof Popper.Utils\\n * @argument {Element} element\\n * @returns {Element} offset parent\\n */\\nexport default function getOffsetParent(element) {\\n  // NOTE: 1 DOM access here\\n  const offsetParent = element &amp;&amp; element.offsetParent;\\n  const nodeName = offsetParent &amp;&amp; offsetParent.nodeName;\\n\\n  if (!nodeName || nodeName === 'BODY' || nodeName === 'HTML') {\\n    if (element) {\\n      return element.ownerDocument.documentElement\\n    }\\n\\n    return document.documentElement;\\n  }\\n\\n  // .offsetParent will return the closest TD or TABLE in case\\n  // no offsetParent is present, I hate this job...\\n  if (\\n    ['TD', 'TABLE'].indexOf(offsetParent.nodeName) !== -1 &amp;&amp;\\n    getStyleComputedProperty(offsetParent, 'position') === 'static'\\n  ) {\\n    return getOffsetParent(offsetParent);\\n  }\\n\\n  return offsetParent;\\n}\\n\"</span>,<span class=\"code-string\">\"import getOffsetParent from './getOffsetParent';\\n\\nexport default function isOffsetContainer(element) {\\n  const { nodeName } = element;\\n  if (nodeName === 'BODY') {\\n    return false;\\n  }\\n  return (\\n    nodeName === 'HTML' || getOffsetParent(element.firstElementChild) === element\\n  );\\n}\\n\"</span>,<span class=\"code-string\">\"/**\\n * Finds the root node (document, shadowDOM root) of the given element\\n * @method\\n * @memberof Popper.Utils\\n * @argument {Element} node\\n * @returns {Element} root node\\n */\\nexport default function getRoot(node) {\\n  if (node.parentNode !== null) {\\n    return getRoot(node.parentNode);\\n  }\\n\\n  return node;\\n}\\n\"</span>,<span class=\"code-string\">\"import isOffsetContainer from './isOffsetContainer';\\nimport getRoot from './getRoot';\\nimport getOffsetParent from './getOffsetParent';\\n\\n/**\\n * Finds the offset parent common to the two provided nodes\\n * @method\\n * @memberof Popper.Utils\\n * @argument {Element} element1\\n * @argument {Element} element2\\n * @returns {Element} common offset parent\\n */\\nexport default function findCommonOffsetParent(element1, element2) {\\n  // This check is needed to avoid errors in case one of the elements isn't defined for any reason\\n  if (!element1 || !element1.nodeType || !element2 || !element2.nodeType) {\\n    return document.documentElement;\\n  }\\n\\n  // Here we make sure to give as \\\"start\\\" the element that comes first in the DOM\\n  const order =\\n    element1.compareDocumentPosition(element2) &amp;\\n    Node.DOCUMENT_POSITION_FOLLOWING;\\n  const start = order ? element1 : element2;\\n  const end = order ? element2 : element1;\\n\\n  // Get common ancestor container\\n  const range = document.createRange();\\n  range.setStart(start, 0);\\n  range.setEnd(end, 0);\\n  const { commonAncestorContainer } = range;\\n\\n  // Both nodes are inside #document\\n  if (\\n    (element1 !== commonAncestorContainer &amp;&amp;\\n      element2 !== commonAncestorContainer) ||\\n    start.contains(end)\\n  ) {\\n    if (isOffsetContainer(commonAncestorContainer)) {\\n      return commonAncestorContainer;\\n    }\\n\\n    return getOffsetParent(commonAncestorContainer);\\n  }\\n\\n  // one of the nodes is inside shadowDOM, find which one\\n  const element1root = getRoot(element1);\\n  if (element1root.host) {\\n    return findCommonOffsetParent(element1root.host, element2);\\n  } else {\\n    return findCommonOffsetParent(element1, getRoot(element2).host);\\n  }\\n}\\n\"</span>,<span class=\"code-string\">\"/**\\n * Gets the scroll value of the given element in the given side (top and left)\\n * @method\\n * @memberof Popper.Utils\\n * @argument {Element} element\\n * @argument {String} side `top` or `left`\\n * @returns {number} amount of scrolled pixels\\n */\\nexport default function getScroll(element, side = 'top') {\\n  const upperSide = side === 'top' ? 'scrollTop' : 'scrollLeft';\\n  const nodeName = element.nodeName;\\n\\n  if (nodeName === 'BODY' || nodeName === 'HTML') {\\n    const html = element.ownerDocument.documentElement;\\n    const scrollingElement = element.ownerDocument.scrollingElement || html;\\n    return scrollingElement[upperSide];\\n  }\\n\\n  return element[upperSide];\\n}\\n\"</span>,<span class=\"code-string\">\"import getScroll from './getScroll';\\n\\n/*\\n * Sum or subtract the element scroll values (left and top) from a given rect object\\n * @method\\n * @memberof Popper.Utils\\n * @param {Object} rect - Rect object you want to change\\n * @param {HTMLElement} element - The element from the function reads the scroll values\\n * @param {Boolean} subtract - set to true if you want to subtract the scroll values\\n * @return {Object} rect - The modifier rect object\\n */\\nexport default function includeScroll(rect, element, subtract = false) {\\n  const scrollTop = getScroll(element, 'top');\\n  const scrollLeft = getScroll(element, 'left');\\n  const modifier = subtract ? -1 : 1;\\n  rect.top += scrollTop * modifier;\\n  rect.bottom += scrollTop * modifier;\\n  rect.left += scrollLeft * modifier;\\n  rect.right += scrollLeft * modifier;\\n  return rect;\\n}\\n\"</span>,<span class=\"code-string\">\"/*\\n * Helper to detect borders of a given element\\n * @method\\n * @memberof Popper.Utils\\n * @param {CSSStyleDeclaration} styles\\n * Result of `getStyleComputedProperty` on the given element\\n * @param {String} axis - `x` or `y`\\n * @return {number} borders - The borders size of the given axis\\n */\\n\\nexport default function getBordersSize(styles, axis) {\\n  const sideA = axis === 'x' ? 'Left' : 'Top';\\n  const sideB = sideA === 'Left' ? 'Right' : 'Bottom';\\n\\n  return (\\n    parseFloat(styles[`border${sideA}Width`], 10) +\\n    parseFloat(styles[`border${sideB}Width`], 10)\\n  );\\n}\\n\"</span>,<span class=\"code-string\">\"/**\\n * Tells if you are running Internet Explorer 10\\n * @method\\n * @memberof Popper.Utils\\n * @returns {Boolean} isIE10\\n */\\nlet isIE10 = undefined;\\n\\nexport default function() {\\n  if (isIE10 === undefined) {\\n    isIE10 = navigator.appVersion.indexOf('MSIE 10') !== -1;\\n  }\\n  return isIE10;\\n}\\n\"</span>,<span class=\"code-string\">\"import isIE10 from './isIE10';\\n\\nfunction getSize(axis, body, html, computedStyle) {\\n  return Math.max(\\n    body[`offset${axis}`],\\n    body[`scroll${axis}`],\\n    html[`client${axis}`],\\n    html[`offset${axis}`],\\n    html[`scroll${axis}`],\\n    isIE10()\\n      ? html[`offset${axis}`] +\\n        computedStyle[`margin${axis === 'Height' ? 'Top' : 'Left'}`] +\\n        computedStyle[`margin${axis === 'Height' ? 'Bottom' : 'Right'}`]\\n      : 0\\n  );\\n}\\n\\nexport default function getWindowSizes() {\\n  const body = document.body;\\n  const html = document.documentElement;\\n  const computedStyle = isIE10() &amp;&amp; getComputedStyle(html);\\n\\n  return {\\n    height: getSize('Height', body, html, computedStyle),\\n    width: getSize('Width', body, html, computedStyle),\\n  };\\n}\\n\"</span>,<span class=\"code-string\">\"/**\\n * Given element offsets, generate an output similar to getBoundingClientRect\\n * @method\\n * @memberof Popper.Utils\\n * @argument {Object} offsets\\n * @returns {Object} ClientRect like output\\n */\\nexport default function getClientRect(offsets) {\\n  return {\\n    ...offsets,\\n    right: offsets.left + offsets.width,\\n    bottom: offsets.top + offsets.height,\\n  };\\n}\\n\"</span>,<span class=\"code-string\">\"import getStyleComputedProperty from './getStyleComputedProperty';\\nimport getBordersSize from './getBordersSize';\\nimport getWindowSizes from './getWindowSizes';\\nimport getScroll from './getScroll';\\nimport getClientRect from './getClientRect';\\nimport isIE10 from './isIE10';\\n\\n/**\\n * Get bounding client rect of given element\\n * @method\\n * @memberof Popper.Utils\\n * @param {HTMLElement} element\\n * @return {Object} client rect\\n */\\nexport default function getBoundingClientRect(element) {\\n  let rect = {};\\n\\n  // IE10 10 FIX: Please, don't ask, the element isn't\\n  // considered in DOM in some circumstances...\\n  // This isn't reproducible in IE10 compatibility mode of IE11\\n  if (isIE10()) {\\n    try {\\n      rect = element.getBoundingClientRect();\\n      const scrollTop = getScroll(element, 'top');\\n      const scrollLeft = getScroll(element, 'left');\\n      rect.top += scrollTop;\\n      rect.left += scrollLeft;\\n      rect.bottom += scrollTop;\\n      rect.right += scrollLeft;\\n    } catch (err) {}\\n  } else {\\n    rect = element.getBoundingClientRect();\\n  }\\n\\n  const result = {\\n    left: rect.left,\\n    top: rect.top,\\n    width: rect.right - rect.left,\\n    height: rect.bottom - rect.top,\\n  };\\n\\n  // subtract scrollbar size from sizes\\n  const sizes = element.nodeName === 'HTML' ? getWindowSizes() : {};\\n  const width =\\n    sizes.width || element.clientWidth || result.right - result.left;\\n  const height =\\n    sizes.height || element.clientHeight || result.bottom - result.top;\\n\\n  let horizScrollbar = element.offsetWidth - width;\\n  let vertScrollbar = element.offsetHeight - height;\\n\\n  // if an hypothetical scrollbar is detected, we must be sure it's not a `border`\\n  // we make this check conditional for performance reasons\\n  if (horizScrollbar || vertScrollbar) {\\n    const styles = getStyleComputedProperty(element);\\n    horizScrollbar -= getBordersSize(styles, 'x');\\n    vertScrollbar -= getBordersSize(styles, 'y');\\n\\n    result.width -= horizScrollbar;\\n    result.height -= vertScrollbar;\\n  }\\n\\n  return getClientRect(result);\\n}\\n\"</span>,<span class=\"code-string\">\"import getStyleComputedProperty from './getStyleComputedProperty';\\nimport includeScroll from './includeScroll';\\nimport getScrollParent from './getScrollParent';\\nimport getBoundingClientRect from './getBoundingClientRect';\\nimport runIsIE10 from './isIE10';\\nimport getClientRect from './getClientRect';\\n\\nexport default function getOffsetRectRelativeToArbitraryNode(children, parent) {\\n  const isIE10 = runIsIE10();\\n  const isHTML = parent.nodeName === 'HTML';\\n  const childrenRect = getBoundingClientRect(children);\\n  const parentRect = getBoundingClientRect(parent);\\n  const scrollParent = getScrollParent(children);\\n\\n  const styles = getStyleComputedProperty(parent);\\n  const borderTopWidth = parseFloat(styles.borderTopWidth, 10);\\n  const borderLeftWidth = parseFloat(styles.borderLeftWidth, 10);\\n\\n  let offsets = getClientRect({\\n    top: childrenRect.top - parentRect.top - borderTopWidth,\\n    left: childrenRect.left - parentRect.left - borderLeftWidth,\\n    width: childrenRect.width,\\n    height: childrenRect.height,\\n  });\\n  offsets.marginTop = 0;\\n  offsets.marginLeft = 0;\\n\\n  // Subtract margins of documentElement in case it's being used as parent\\n  // we do this only on HTML because it's the only element that behaves\\n  // differently when margins are applied to it. The margins are included in\\n  // the box of the documentElement, in the other cases not.\\n  if (!isIE10 &amp;&amp; isHTML) {\\n    const marginTop = parseFloat(styles.marginTop, 10);\\n    const marginLeft = parseFloat(styles.marginLeft, 10);\\n\\n    offsets.top -= borderTopWidth - marginTop;\\n    offsets.bottom -= borderTopWidth - marginTop;\\n    offsets.left -= borderLeftWidth - marginLeft;\\n    offsets.right -= borderLeftWidth - marginLeft;\\n\\n    // Attach marginTop and marginLeft because in some circumstances we may need them\\n    offsets.marginTop = marginTop;\\n    offsets.marginLeft = marginLeft;\\n  }\\n\\n  if (\\n    isIE10\\n      ? parent.contains(scrollParent)\\n      : parent === scrollParent &amp;&amp; scrollParent.nodeName !== 'BODY'\\n  ) {\\n    offsets = includeScroll(offsets, parent);\\n  }\\n\\n  return offsets;\\n}\\n\"</span>,<span class=\"code-string\">\"import getOffsetRectRelativeToArbitraryNode from './getOffsetRectRelativeToArbitraryNode';\\nimport getScroll from './getScroll';\\nimport getClientRect from './getClientRect';\\n\\nexport default function getViewportOffsetRectRelativeToArtbitraryNode(element) {\\n  const html = element.ownerDocument.documentElement;\\n  const relativeOffset = getOffsetRectRelativeToArbitraryNode(element, html);\\n  const width = Math.max(html.clientWidth, window.innerWidth || 0);\\n  const height = Math.max(html.clientHeight, window.innerHeight || 0);\\n\\n  const scrollTop = getScroll(html);\\n  const scrollLeft = getScroll(html, 'left');\\n\\n  const offset = {\\n    top: scrollTop - relativeOffset.top + relativeOffset.marginTop,\\n    left: scrollLeft - relativeOffset.left + relativeOffset.marginLeft,\\n    width,\\n    height,\\n  };\\n\\n  return getClientRect(offset);\\n}\\n\"</span>,<span class=\"code-string\">\"import getStyleComputedProperty from './getStyleComputedProperty';\\nimport getParentNode from './getParentNode';\\n\\n/**\\n * Check if the given element is fixed or is inside a fixed parent\\n * @method\\n * @memberof Popper.Utils\\n * @argument {Element} element\\n * @argument {Element} customContainer\\n * @returns {Boolean} answer to \\\"isFixed?\\\"\\n */\\nexport default function isFixed(element) {\\n  const nodeName = element.nodeName;\\n  if (nodeName === 'BODY' || nodeName === 'HTML') {\\n    return false;\\n  }\\n  if (getStyleComputedProperty(element, 'position') === 'fixed') {\\n    return true;\\n  }\\n  return isFixed(getParentNode(element));\\n}\\n\"</span>,<span class=\"code-string\">\"import getScrollParent from './getScrollParent';\\nimport getParentNode from './getParentNode';\\nimport findCommonOffsetParent from './findCommonOffsetParent';\\nimport getOffsetRectRelativeToArbitraryNode from './getOffset