class=\"code-string\">\"import getOppositePlacement from '../utils/getOppositePlacement';\\nimport getOppositeVariation from '../utils/getOppositeVariation';\\nimport getPopperOffsets from '../utils/getPopperOffsets';\\nimport runModifiers from '../utils/runModifiers';\\nimport getBoundaries from '../utils/getBoundaries';\\nimport isModifierEnabled from '../utils/isModifierEnabled';\\nimport clockwise from '../utils/clockwise';\\n\\nconst BEHAVIORS = {\\n  FLIP: 'flip',\\n  CLOCKWISE: 'clockwise',\\n  COUNTERCLOCKWISE: 'counterclockwise',\\n};\\n\\n/**\\n * @function\\n * @memberof Modifiers\\n * @argument {Object} data - The data object generated by update method\\n * @argument {Object} options - Modifiers configuration and options\\n * @returns {Object} The data object, properly modified\\n */\\nexport default function flip(data, options) {\\n  // if `inner` modifier is enabled, we can't use the `flip` modifier\\n  if (isModifierEnabled(data.instance.modifiers, 'inner')) {\\n    return data;\\n  }\\n\\n  if (data.flipped &amp;&amp; data.placement === data.originalPlacement) {\\n    // seems like flip is trying to loop, probably there's not enough space on any of the flippable sides\\n    return data;\\n  }\\n\\n  const boundaries = getBoundaries(\\n    data.instance.popper,\\n    data.instance.reference,\\n    options.padding,\\n    options.boundariesElement\\n  );\\n\\n  let placement = data.placement.split('-')[0];\\n  let placementOpposite = getOppositePlacement(placement);\\n  let variation = data.placement.split('-')[1] || '';\\n\\n  let flipOrder = [];\\n\\n  switch (options.behavior) {\\n    case BEHAVIORS.FLIP:\\n      flipOrder = [placement, placementOpposite];\\n      break;\\n    case BEHAVIORS.CLOCKWISE:\\n      flipOrder = clockwise(placement);\\n      break;\\n    case BEHAVIORS.COUNTERCLOCKWISE:\\n      flipOrder = clockwise(placement, true);\\n      break;\\n    default:\\n      flipOrder = options.behavior;\\n  }\\n\\n  flipOrder.forEach((step, in