isVertical &amp;&amp; variation === 'end' &amp;&amp; overflowsBottom));\\n\\n    if (overlapsRef || overflowsBoundaries || flippedVariation) {\\n      // this boolean to detect any flip loop\\n      data.flipped = true;\\n\\n      if (overlapsRef || overflowsBoundaries) {\\n        placement = flipOrder[index + 1];\\n      }\\n\\n      if (flippedVariation) {\\n        variation = getOppositeVariation(variation);\\n      }\\n\\n      data.placement = placement + (variation ? '-' + variation : '');\\n\\n      // this object contains `position`, we want to preserve it along with\\n      // any additional property we may add in the future\\n      data.offsets.popper = {\\n        ...data.offsets.popper,\\n        ...getPopperOffsets(\\n          data.instance.popper,\\n          data.offsets.reference,\\n          data.placement\\n        ),\\n      };\\n\\n      data = runModifiers(data.instance.modifiers, data, 'flip');\\n    }\\n  });\\n  return data;\\n}\\n\"</span>,<span class=\"code-string\">\"/**\\n * @function\\n * @memberof Modifiers\\n * @argument {Object} data - The data object generated by update method\\n * @argument {Object} options - Modifiers configuration and options\\n * @returns {Object} The data object, properly modified\\n */\\nexport default function keepTogether(data) {\\n  const { popper, reference } = data.offsets;\\n  const placement = data.placement.split('-')[0];\\n  const floor = Math.floor;\\n  const isVertical = ['top', 'bottom'].indexOf(placement) !== -1;\\n  const side = isVertical ? 'right' : 'bottom';\\n  const opSide = isVertical ? 'left' : 'top';\\n  const measurement = isVertical ? 'width' : 'height';\\n\\n  if (popper[side] &lt; floor(reference[opSide])) {\\n    data.offsets.popper[opSide] =\\n      floor(reference[opSide]) - popper[measurement];\\n  }\\n  if (popper[opSide] &gt; floor(reference[side])) {\\n    data.offsets.popper[opSide] = floor(reference[side]);\\n  }\\n\\n  return data;\\n}\\n\"</span>,<span class=\"code-string\">\"import isNumeric from '../utils/isNumeric';\\nimport getClientRect from '../utils/getClientRect';\\nimport find from '../utils/find';\\n\\n/**\\n * Converts a string containing value + unit into a px value number\\n * @function\\n * @memberof {modifiers~offset}\\n * @private\\n * @argument {String} str - Value + unit string\\n * @argument {String} measurement - `height` or `width`\\n * @argument {Object} popperOffsets\\n * @argument {Object} referenceOffsets\\n * @returns {Number|String}\\n * Value in pixels, or original string if no values were extracted\\n */\\nexport function toValue(str, measurement, popperOffsets, referenceOffsets) {\\n  // separate value from unit\\n  const split = str.match(/((?:\\\\-|\\\\+)?\\\\d*\\\\.?\\\\d*)(.*)/);\\n  const value = +split[1];\\n  const unit = split[2];\\n\\n  // If it's not a number it's an operator, I guess\\n  if (!value) {\\n    return str;\\n  }\\n\\n  if (unit.indexOf('%') === 0) {\\n    let element;\\n    switch (unit) {\\n      case '%p':\\n        element = popperOffsets;\\n        break;\\n      case '%':\\n      case '%r':\\n      default:\\n        element = referenceOffsets;\\n    }\\n\\n    const rect = getClientRect(element);\\n    return rect[measurement] / 100 * value;\\n  } else if (unit === 'vh' || unit === 'vw') {\\n    // if is a vh or vw, we calculate the size based on the viewport\\n    let size;\\n    if (unit === 'vh') {\\n      size = Math.max(\\n        document.documentElement.clientHeight,\\n        window.innerHeight || 0\\n      );\\n    } else {\\n      size = Math.max(\\n        document.documentElement.clientWidth,\\n        window.innerWidth || 0\\n      );\\n    }\\n    return size / 100 * value;\\n  } else {\\n    // if is an explicit pixel unit, we get rid of the unit and keep the value\\n    // if is an implicit unit, it's px, and we return just the value\\n    return value;\\n  }\\n}\\n\\n/**\\n * Parse an `offset` string to extrapolate `x` and `y` numeric offsets.\\n * @function\\n * @memberof {modifiers~offset}\\n * @private\\n * @argument {String} offset\\n * @argument {Object} popperOffsets\\n * @argument {Object} referenceOffsets\\n * @argument {String} basePlacement\\n * @returns {Array} a two cells array with x and y offsets in numbers\\n */\\nexport function parseOffset(\\n  offset,\\n  popperOffsets,\\n  referenceOffsets,\\n  basePlacement\\n) {\\n  const offsets = [0, 0];\\n\\n  // Use height if placement is left or right and index is 0 otherwise use width\\n  // in this way the first offset will use an axis and the second one\\n  // will use the other one\\n  const useHeight = ['right', 'left'].indexOf(basePlacement) !== -1;\\n\\n  // Split the offset string to obtain a list of values and operands\\n  // The regex addresses values with the plus or minus sign in front (+10, -20, etc)\\n  const fragments = offset.split(/(\\\\+|\\\\-)/).map(frag =&gt; frag.trim());\\n\\n  // Detect if the offset string contains a pair of values or a single one\\n  // they could be separated by comma or space\\n  const divider = fragments.indexOf(\\n    find(fragments, frag =&gt; frag.search(/,|\\\\s/) !== -1)\\n  );\\n\\n  if (fragments[divider] &amp;&amp; fragments[divider].indexOf(',') === -1) {\\n    console.warn(\\n      'Offsets separated by white space(s) are deprecated, use a comma (,) instead.'\\n    );\\n  }\\n\\n  // If divider is found, we divide the list of values and operands to divide\\n  // them by ofset X and Y.\\n  const splitRegex = /\\\\s*,\\\\s*|\\\\s+/;\\n  let ops = divider !== -1\\n    ? [\\n        fragments\\n          .slice(0, divider)\\n          .concat([fragments[divider].split(splitRegex)[0]]),\\n        [fragments[divider].split(splitRegex)[1]].concat(\\n          fragments.slice(divider + 1)\\n        ),\\n      ]\\n    : [fragments];\\n\\n  // Convert the values with units to absolute pixels to allow our computations\\n  ops = ops.map((op, index) =&gt; {\\n    // Most of the units rely on the orientation of the popper\\n    const measurement = (index === 1 ? !useHeight : useHeight)\\n      ? 'height'\\n      : 'width';\\n    let mergeWithPrevious = false;\\n    return (\\n      op\\n        // This aggregates any `+` or `-` sign that aren't considered operators\\n        // e.g.: 10 + +5 =&gt; [10, +, +5]\\n        .reduce((a, b) =&gt; {\\n          if (a[a.length - 1] === '' &amp;&amp; ['+', '-'].indexOf(b) !== -1) {\\n            a[a.length - 1] = b;\\n            mergeWithPrevious = true;\\n            return a;\\n          } else if (mergeWithPrevious) {\\n            a[a.length - 1] += b;\\n            mergeWithPrevious = false;\\n            return a;\\n          } else {\\n            return a.concat(b);\\n          }\\n        }, [])\\n        // Here we convert the string values into number values (in px)\\n        .map(str =&gt; toValue(str, measurement, popperOffsets, referenceOffsets))\\n    );\\n  });\\n\\n  // Loop trough the offsets arrays and execute the operations\\n  ops.forEach((op, index) =&gt; {\\n    op.forEach((frag, index2) =&gt; {\\n      if (isNumeric(frag)) {\\n        offsets[index] += frag * (op[index2 - 1] === '-' ? -1 : 1);\\n      }\\n    });\\n  });\\n  return offsets;\\n}\\n\\n/**\\n * @function\\n * @memberof Modifiers\\n * @argument {Object} data - The data object generated by update method\\n * @argument {Object} options - Modifiers configuration and options\\n * @argument {Number|String} options.offset=0\\n * The offset value as described in the modifier description\\n * @returns {Object} The data object, properly modified\\n */\\nexport default function offset(data, { offset }) {\\n  const { placement, offsets: { popper, reference } } = data;\\n  const basePlacement = placement.split('-')[0];\\n\\n  let offsets;\\n  if (isNumeric(+offset)) {\\n    offsets = [+offset, 0];\\n  } else {\\n    offsets = parseOffset(offset, popper, reference, basePlacement);\\n  }\\n\\n  if (basePlacement === 'left') {\\n    popper.top += offsets[0];\\n    popper.left -= offsets[1];\\n  } else if (basePlacement === 'right') {\\n    popper.top += offsets[0];\\n    popper.left += offsets[1];\\n  } else if (basePlacement === 'top') {\\n    popper.left += offsets[0];\\n    popper.top -= offsets[1];\\n  } else if (basePlacement === 'bottom') {\\n    popper.left += offsets[0];\\n    popper.top += offsets[1];\\n  }\\n\\n  data.popper = popper;\\n  return data;\\n}\\n\"</span>,<span class=\"code-string\">\"import getOffsetParent from '../utils/getOffsetParent';\\nimport getBoundaries from '../utils/getBoundaries';\\n\\n/**\\n * @function\\n * @memberof Modifiers\\n * @argument {Object} data - The data object generated by `update` method\\n * @argument {Object} options - Modifiers configuration and options\\n * @returns {Object} The data object, properly modified\\n */\\nexport default function preventOverflow(data, options) {\\n  let boundariesElement =\\n    options.boundariesElement || getOffsetParent(data.instance.popper);\\n\\n  // If offsetParent is the reference element, we really want to\\n  // go one step up and use the next offsetParent as reference to\\n  // avoid to make this modifier completely useless and look like broken\\n  if (data.instance.reference === boundariesElement) {\\n    boundariesElement = getOffsetParent(boundariesElement);\\n  }\\n\\n  const boundaries = getBoundaries(\\n    data.instance.popper,\\n    data.instance.reference,\\n    options.padding,\\n    boundariesElement\\n  );\\n  options.boundaries = boundaries;\\n\\n  const order = options.priority;\\n  let popper = data.offsets.popper;\\n\\n  const check = {\\n    primary(placement) {\\n      let value = popper[placement];\\n      if (\\n        popper[placement] &lt; boundaries[placement] &amp;&amp;\\n        !options.escapeWithReference\\n      ) {\\n        value = Math.max(popper[placement], boundaries[placement]);\\n      }\\n      return { [placement]: value };\\n    },\\n    secondary(placement) {\\n      const mainSide = placement === 'right' ? 'left' : 'top';\\n      let value = popper[mainSide];\\n      if (\\n        popper[placement] &gt; boundaries[placement] &amp;&amp;\\n        !options.escapeWithReference\\n      ) {\\n        value = Math.min(\\n          popper[mainSide],\\n          boundaries[placement] -\\n            (placement === 'right' ? popper.width : popper.height)\\n        );\\n      }\\n      return { [mainSide]: value };\\n    },\\n  };\\n\\n  order.forEach(placement =&gt; {\\n    const side = ['left', 'top'].indexOf(placement) !== -1\\n      ? 'primary'\\n      : 'secondary';\\n    popper = { ...popper, ...check[side](placement) };\\n  });\\n\\n  data.offsets.popper = popper;\\n\\n  return data;\\n}\\n\"</span>,<span class=\"code-string\">\"/**\\n * @function\\n * @memberof Modifiers\\n * @argument {Object} data - The data object generated by `update` method\\n * @argument {Object} options - Modifiers configuration and options\\n * @returns {Object} The data object, properly modified\\n */\\nexport default function shift(data) {\\n  const placement = data.placement;\\n  const basePlacement = placement.split('-')[0];\\n  const shiftvariation = placement.split('-')[1];\\n\\n  // if shift shiftvariation is specified, run the modifier\\n  if (shiftvariation) {\\n    const { reference, popper } = data.offsets;\\n    const isVertical = ['bottom', 'top'].indexOf(basePlacement) !== -1;\\n    const side = isVertical ? 'left' : 'top';\\n    const measurement = isVertical ? 'width' : 'height';\\n\\n    const shiftOffsets = {\\n      start: { [side]: reference[side] },\\n      end: {\\n        [side]: reference[side] + reference[measurement] - popper[measurement],\\n      },\\n    };\\n\\n    data.offsets.popper = { ...popper, ...shiftOffsets[shiftvariation] };\\n  }\\n\\n  return data;\\n}\\n\"</span>,<span class=\"code-string\">\"import isModifierRequired from '../utils/isModifierRequired';\\nimport find from '../utils/find';\\n\\n/**\\n * @function\\n * @memberof Modifiers\\n * @argument {Object} data - The data object generated by update method\\n * @argument {Object} options - Modifiers configuration and options\\n * @returns {Object} The data object, properly modified\\n */\\nexport default function hide(data) {\\n  if (!isModifierRequired(data.instance.modifiers, 'hide', 'preventOverflow')) {\\n    return data;\\n  }\\n\\n  const refRect = data.offsets.reference;\\n  const bound = find(\\n    data.instance.modifiers,\\n    modifier =&gt; modifier.name === 'preventOverflow'\\n  ).boundaries;\\n\\n  if (\\n    refRect.bottom &lt; bound.top ||\\n    refRect.left &gt; bound.right ||\\n    refRect.top &gt; bound.bottom ||\\n    refRect.right &lt; bound.left\\n  ) {\\n    // Avoid unnecessary DOM access if visibility hasn't changed\\n    if (data.hide === true) {\\n      return data;\\n    }\\n\\n    data.hide = true;\\n    data.attributes['x-out-of-boundaries'] = '';\\n  } else {\\n    // Avoid unnecessary DOM access if visibility hasn't changed\\n    if (data.hide === false) {\\n      return data;\\n    }\\n\\n    data.hide = false;\\n    data.attributes['x-out-of-boundaries'] = false;\\n  }\\n\\n  return data;\\n}\\n\"</span>,<span class=\"code-string\">\"import getClientRect from '../utils/getClientRect';\\nimport getOppositePlacement from '../utils/getOppositePlacement';\\n\\n/**\\n * @function\\n * @memberof Modifiers\\n * @argument {Object} data - The data object generated by `update` method\\n * @argument {Object} options - Modifiers configuration and options\\n * @returns {Object} The data object, properly modified\\n */\\nexport default function inner(data) {\\n  const placement = data.placement;\\n  const basePlacement = placement.split('-')[0];\\n  const { popper, reference } = data.offsets;\\n  const isHoriz = ['left', 'right'].indexOf(basePlacement) !== -1;\\n\\n  const subtractLength = ['top', 'left'].indexOf(basePlacement) === -1;\\n\\n  popper[isHoriz ? 'left' : 'top'] =\\n    reference[basePlacement] -\\n    (subtractLength ?